// Generated by Node from pi v1.4.0 utils/identity.ts (adc5fa9f8/04a93bad8).
// Regenerate: node --experimental-strip-types ai/testdata/identity/generate.mjs ./pi > ai/testdata/identity/golden.json
func TestMergeClientIdentityJSONParity(t *testing.T) {
	data, err := os.ReadFile("testdata/identity/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden struct {
		Merges []struct {
			Sources []*ClientIdentity
			Want    *string
		}
	}
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatal(err)
	}
	for index, tc := range golden.Merges {
		got := MergeClientIdentity(tc.Sources...)
		if tc.Want == nil {
			if got != nil {
				t.Fatalf("case %d: expected undefined, got %+v", index, got)
			}
			continue
		}
		encoded, err := MarshalJSON(got)
		if err != nil {
			t.Fatal(err)
		}
		if string(encoded) != *tc.Want {
			t.Fatalf("case %d: merged = %s; want %s", index, encoded, *tc.Want)
		}
	}
}

func TestClientIdentityJSONRoundTrip(t *testing.T) {
	data, err := os.ReadFile("testdata/identity/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden struct{ RoundTrips []string }
	if err := json.Unmarshal(data, &golden); err != nil {
		t.Fatal(err)
	}
	for _, input := range golden.RoundTrips {
		t.Run(input, func(t *testing.T) {
			var identity ClientIdentity
			if err := json.Unmarshal([]byte(input), &identity); err != nil {
				t.Fatal(err)
			}
			encoded, err := MarshalJSON(identity)
			if err != nil {
				t.Fatal(err)
			}
			if string(encoded) != input {
				t.Fatalf("round trip = %s; want %s", encoded, input)
			}
		})
	}
}
